	events.set('Foo', [onFoo]);
	events.set('FOO', [onFOO]);

	inst.emit('Foo', 'Foo arg');
	inst.emit('FOO', 'FOO arg');

	expect(onFoo).to.have.been.calledOnce.and.calledWith('Foo arg');
	expect(onFOO).to.have.been.calledOnce.and.calledWith('FOO arg');
});

